const message = $json.message || {};
  const configuredUserId = String($json.allowed_user_id || "").trim();
  const spreadsheetId = String($json.spreadsheet_id || "").trim();

  if (!configuredUserId || configuredUserId === "COLE_SEU_TELEGRAM_USER_ID") {
    throw new Error("Configuração pendente: informe seu Telegram User ID no nó CONFIGURE AQUI.");
  }
  if (!spreadsheetId || spreadsheetId === "COLE_O_ID_DA_PLANILHA") {
    throw new Error("Configuração pendente: informe o ID da planilha no nó CONFIGURE AQUI.");
  }

  const senderId = String(message.from?.id || "");
  if (senderId !== configuredUserId) return [];

  let mediaType = "unsupported";
  let fileId = "";
  let mimeType = "";
  let durationSeconds = "";
  let fileSize = 0;
  let unsupportedReason = "";
  const caption = String(message.caption || "").trim();
  let text = String(message.text || "").trim();

  if (message.voice) {
    mediaType = "audio";
    fileId = String(message.voice.file_id || "");
    mimeType = String(message.voice.mime_type || "audio/ogg");
    durationSeconds = String(message.voice.duration || "");
    fileSize = Number(message.voice.file_size || 0);
  } else if (message.audio) {
    mediaType = "audio";
    fileId = String(message.audio.file_id || "");
    mimeType = String(message.audio.mime_type || "audio/mpeg");
    durationSeconds = String(message.audio.duration || "");
    fileSize = Number(message.audio.file_size || 0);
  } else if (Array.isArray(message.photo) && message.photo.length) {
    const image = message.photo[message.photo.length - 1];
    mediaType = "image";
    fileId = String(image.file_id || "");
    mimeType = "image/jpeg";
    fileSize = Number(image.file_size || 0);
  } else if (message.document && String(message.document.mime_type || "").startsWith("image/")) {
    mediaType = "image";
    fileId = String(message.document.file_id || "");
    mimeType = String(message.document.mime_type || "image/jpeg");
    fileSize = Number(message.document.file_size || 0);
  } else if (text || caption) {
    mediaType = "text";
    text = text || caption;
  } else {
    unsupportedReason = "Envie uma mensagem de texto, um áudio/voz ou uma imagem.";
  }

  if (mediaType === "audio" && fileSize > 25 * 1024 * 1024) {
    mediaType = "unsupported";
    unsupportedReason = "O áudio ultrapassa o limite de 25 MB para transcrição. Envie uma versão menor.";
  }

  return [{
    json: {
      chat_id: String(message.chat?.id || ""),
      user_id: senderId,
      first_name: message.from?.first_name || "Gabriel",
      username: message.from?.username || "",
      message_id: String(message.message_id || ""),
      created_at: new Date((message.date || Math.floor(Date.now() / 1000)) * 1000).toISOString(),
      texto: text,
      media_type: mediaType,
      media_file_id: fileId,
      media_mime_type: mimeType,
      media_duration_seconds: durationSeconds,
      media_file_size: fileSize,
      media_caption: caption,
      transcricao_midia: "",
      unsupported_reason: unsupportedReason
    }
  }];

