  const titleCase = (value) => {
    const text = String(value || "");
    return text ? text.charAt(0).toUpperCase() + text.slice(1) : "";
  };
  const formatDate = (value) => {
    const date = new Date(value);
    return Number.isNaN(date.getTime())
      ? esc(value || "Data não informada")
      : new Intl.DateTimeFormat("pt-BR", {
          dateStyle: "medium",
          timeStyle: "short",
          timeZone: "America/Sao_Paulo"
        }).format(date);
  };

  const rows = $input.all()
    .map((item) => item.json)
    .filter((row) => row && Object.keys(row).length)
    .sort((a, b) => String(b.criado_em || "").localeCompare(String(a.criado_em || "")));

  const counts = {};
  rows.forEach((row) => {
    const category = String(row.categoria || "Sem categoria").trim() || "Sem categoria";
    counts[category] = (counts[category] || 0) + 1;
  });
  const categories = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  const topCategory = categories[0]?.[0] || "—";
  const highPotential = rows.filter((row) => String(row.potencial || "").toLowerCase() === "alto").length;
  const lastThirtyDays = rows.filter((row) => {
    const time = new Date(row.criado_em).getTime();
    return Number.isFinite(time) && Date.now() - time <= 30 * 24 * 60 * 60 * 1000;
  }).length;
  const maxCount = Math.max(1, ...categories.map((entry) => entry[1]));

  const categoryOptions = categories
    .map(([name]) => '<option value="' + esc(name) + '">' + esc(name) + "</option>")
    .join("");

  const categoryBars = categories.length
    ? categories.map(([name, count]) => {
        const width = Math.max(8, Math.round((count / maxCount) * 100));
        return '<div class="bar-row"><div class="bar-label"><span>' + esc(name) +
          "</span><strong>" + count + '</strong></div><div class="bar-track"><div class="bar-fill" style="width:' +
          width + '%"></div></div></div>';
      }).join("")
    : '<p class="empty-inline">As categorias aparecerão depois que você registrar ideias.</p>';

  const cards = rows.length
    ? rows.map((row, index) => {
        const category = String(row.categoria || "Sem categoria").trim() || "Sem categoria";
        const tags = String(row.tags || "").split(",").map((tag) => tag.trim()).filter(Boolean);
        const searchable = [
          row.titulo, row.resumo, row.ideia_original, row.transcricao_midia, row.legenda_midia, row.tipo_entrada, category, row.subcategoria, row.tags
        ].join(" ").toLowerCase();
        const tagHtml = tags.length
          ? tags.map((tag) => '<span class="tag">' + esc(tag) + "</span>").join("")
          : '<span class="tag muted">Sem tags</span>';
        return '<article class="idea-card" data-category="' + esc(category) +
          '" data-search="' + esc(searchable) + '">' +
          '<div class="card-top"><div class="idea-number">' + String(index + 1).padStart(2, "0") +
          '</div><div class="card-heading"><div class="eyebrow">' + esc(category) +
          (row.subcategoria ? " · " + esc(row.subcategoria) : "") +
          (row.tipo_entrada ? " · " + esc(row.tipo_entrada) : "") + '</div><h3>' +
          esc(row.titulo || "Ideia sem título") + '</h3></div><span class="potential">' +
          esc(titleCase(row.potencial || "Não avaliado")) + "</span></div>" +
          '<p class="summary">' + esc(row.resumo || row.ideia_original || "Sem resumo.") + "</p>" +
          (row.ideia_original && row.resumo && row.ideia_original !== row.resumo
            ? '<details><summary>' +
              (row.tipo_entrada === "Áudio" ? "Ver transcrição completa" :
               row.tipo_entrada === "Imagem" ? "Ver transcrição visual e descrição" :
               "Ver pensamento original") +
              '</summary><p>' + esc(row.ideia_original) + "</p></details>"
            : "") +
          '<div class="card-footer"><div class="tags">' + tagHtml +
          '</div><time>' + formatDate(row.criado_em) + "</time></div></article>";
      }).join("")
    : '<div class="empty-state"><div class="empty-icon">SB</div><h3>Seu Second Brain está pronto</h3>' +
      "<p>Envie uma ideia pelo Telegram para começar a construir este histórico.</p></div>";

